mapper.select:
select z.DZZDM, count(1) as PARTYCOUNT, sum(case when c.ZZLB in('100','200') then 1 else 0 end) as NUM_DW, -- 党委= sum(case when c.ZZLB = '300' then 1 else 0 end) as NUM_DZZ, -- 党总支 sum(case when c.ZZLB = '400' then 1 else 0 end) as NUM_DZB, -- 党支部 sum(case when c.ZZLB = '500' then 1 else 0 end) as NUM_DXZ, -- 党小组 sum(case when c.ZZLB = '300' and c.JCZZFL='71' then 1 else 0 end) as NUM_DZZ_CJ, -- 院系党总支 sum(case when c.ZZLB = '300' and c.JCZZFL='51' then 1 else 0 end) as NUM_DZZ_LTX, -- 团委休党总支 sum(case when c.ZZLB = '400' and c.JCZZFL='21' then 1 else 0 end) as NUM_DZB_CJ, -- 机关党支部 sum(case when c.ZZLB = '400' and c.JCZZFL='71' then 1 else 0 end) as NUM_DZB_KS, -- 院系党支部 sum(case when c.ZZLB = '400' and c.JCZZFL='13' then 1 else 0 end) as NUM_DZB_BZ, -- 班组党支部 sum(case when c.ZZLB = '400' and c.JCZZFL='51' then 1 else 0 end) as NUM_DZB_LTX -- 团委休党支部 from ZZ_ZZQKXX z inner join ( select z.DZZDM,z.DZZMC,fb.ZZLB,fb.JCZZFL from ZZ_ZZQKXX z inner join ZZ_ZZQKXXFB fb on z.DZZDM = fb.DZZDM ) c on z.DZZDM = substr(c.DZZDM, 1, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, sum(s.NUM_XFG) as NUM_XFG, sum(s.NUM_ZRQ) as NUM_ZRQ from ZZ_ZZQKXX z inner join ( select s.PARTYCODE, sum(case when s.CGJQTYPE=1 then 1 else 0 end) as NUM_XFG, sum(case when s.CGJQTYPE=2 then 1 else 0 end) as NUM_ZRQ from CGJQ_POSTAREA_SCORE s where s.GQTYPE=1 and s.OPERATESTATE not in('D')
and s.YEAR=#{year}
group by s.PARTYCODE ) s on z.DZZDM=substr(s.PARTYCODE, 1, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, sum(b.NUM_ZD) as NUM_ZD, -- 站段 sum(b.NUM_JT) as NUM_JT, -- 集团 sum(b.NUM_GT) as NUM_GT -- 国铁 from ZZ_ZZQKXX z inner join ( select b.PARTYCODE, sum(case when b.CREATTYPE=1 then 1 else 0 end) as NUM_ZD, -- 站段 sum(case when b.CREATTYPE=2 then 1 else 0 end) as NUM_JT, -- 集团 sum(case when b.CREATTYPE=3 then 1 else 0 end) as NUM_GT -- 国铁 from dj_brand b where 1=1 and b.OPERATESTATE not in ('D')
and Extract(year from b.BRANDTIME)=#{year}
group by b.PARTYCODE ) b on z.DZZDM=substr(b.PARTYCODE, 1, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, sum(NUM) as NUM from ZZ_ZZQKXX z inner join ( select r.PARTYCODE, sum(1) as NUM from dj_partyActivityRoom r where 1=1 and r.OPERATESTATE not in ('D') group by r.PARTYCODE ) r on z.DZZDM=substr(r.PARTYCODE, 1, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, sum(NUM) as NUM from ZZ_ZZQKXX z inner join ( select p.PARTYCODE, sum(1) as NUM from PUB_PUBLICITYPOSITION p where 1=1 and p.OPERATESTATE not in ('D') group by p.PARTYCODE ) p on z.DZZDM=substr(p.PARTYCODE, 1, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, sum(NUM) as NUM from ZZ_ZZQKXX z inner join ( select w.PARTYCODE,sum(1) as NUM from dj_wxGroup w where 1=1 and w.OPERATESTATE not in ('D') group by w.PARTYCODE ) w on z.DZZDM=substr(w.PARTYCODE, 1, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, sum(NUM_YHJDZB) as NUM_YHJDZB from ZZ_ZZQKXX z inner join ( select z.DZZDM, sum(case when fb.ZZLB = '400' then 1 else 0 end) as NUM_YHJDZB from ZZ_ZZQKXX z inner join ZZ_ZZQKXXFB fb on z.DZZDM = fb.DZZDM inner join ( select DZZDM from ZZ_BZJCXX where substr(GJJMRQ, 1, 4) = #{year} group by DZZDM union select DZZDM from ZZ_ZZQKXX where substr(JLDZZRQ,1,4) = #{year} ) c on z.DZZDM=c.DZZDM group by z.DZZDM ) c on z.DZZDM = substr(c.DZZDM, 1, length(z.DZZDM)) where 1 = 1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, sum(NUM_DZBHJS) as NUM_DZBHJS from ZZ_ZZQKXX z inner join ( select z.DZZDM, sum(case when fb.ZZLB = '400' then 1 else 0 end) as NUM_DZBHJS from ZZ_ZZQKXX z inner join ZZ_ZZQKXXFB fb on z.DZZDM = fb.DZZDM inner join ( select DZZDM from ZZ_BZJCXX where substr(LDJTDXRQ, 1, 4) = #{year} group by DZZDM union select DZZDM from ZZ_ZZQKXX where substr(JLDZZRQ,1,4) = #{year} ) c on z.DZZDM=c.DZZDM group by z.DZZDM ) c on z.DZZDM = substr(c.DZZDM, 1, length(z.DZZDM)) where 1 = 1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, sum(NUM_ZZ) as NUM_ZZ, -- 专职 sum(NUM_JZ) as NUM_JZ, -- 兼职 sum(NUM_GZ) as NUM_GZ -- 挂职副书记 from ZZ_ZZQKXX z inner join ( select c.DZZDM, sum(case when c.ZZJZQK='1' then 1 else 0 end) as NUM_ZZ, -- 专职 sum(case when c.ZZJZQK='2' then 1 else 0 end) as NUM_JZ, -- 兼职 sum(case when c.ZZJZQK='3' then 1 else 0 end) as NUM_GZ -- 挂职副书记 from ZZ_BZCYXX c inner join ZZ_ZZQKXXFB t on c.DZZDM = t.DZZDM and c.JC = t.LDJTJC inner join VM_RYJBXX us on c.RYBM=us.RYBM where c.ZWMC in('H010','H013') group by c.DZZDM ) c on z.DZZDM = substr(c.DZZDM, 1, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, sum(NUM) as NUM from ZZ_ZZQKXX z inner join ( select w.DZZDM,sum(1) as NUM from DJ_DNGHBF w inner join DJ_DNGHBFMX d on w.ID=d.DNGHBFID where 1=1 and w.OPERATESTATE not in ('D')
and Extract(year from d.CAREDATE)=#{year}
group by w.DZZDM ) w on z.DZZDM=substr(w.DZZDM, 1, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, sum(NUM_JZXX) as NUM_JZXX, sum(NUM_ZTYT) as NUM_ZTYT, sum(NUM_DXJL) as NUM_DXJL from ZZ_ZZQKXX z inner join ( select f.DW_ID as dzzdm, sum(case when f.STUDY_MODALITY_CODE='1' then 1 else 0 end) as NUM_JZXX, -- 集中学习 sum(case when f.STUDY_MODALITY_CODE='2' then 1 else 0 end) as NUM_ZTYT, -- 专题研讨 sum(case when f.STUDY_MODALITY_CODE='5' then 1 else 0 end) as NUM_DXJL -- 督学交流 from ZZ_ZXZXX_FA f where 1=1 and (f.DELETED=0 or f.deleted is null)
and Extract(year from f.STUDY_START_TIME)=#{year}
group by f.DW_ID ) f on z.DZZDM=f.DZZDM -- on z.DZZDM=substr(f.DZZDM, 0, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, round(sum(case when f.count>0 then round(ifnull(f.absentCount_JZXX,0)/f.count,4) else 0 end)/count(1),4)*100 as JZXXCQL -- 集中学习出勤率 from ZZ_ZZQKXX z inner join ( select f.ID,f.DW_ID as DZZDM, count(1) as count, sum(case when (u.absent is null or u.absent=0) then 1 else 0 end) as absentCount_JZXX from ZZ_ZXZXX_FA f inner join ZZ_ZXZXX_CJLDBZ u on f.ID=u.CASE_ID where 1=1 and (f.deleted = 0 or f.deleted is null) and (u.deleted = 0 or u.deleted is null) and f.STUDY_MODALITY_CODE='1'
and Extract(year from f.STUDY_START_TIME)=#{year}
group by f.ID,f.DW_ID ) f on z.DZZDM=f.DZZDM -- on z.DZZDM=substr(f.DZZDM, 0, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM,f.STUDY_START_TIME, round(sum(case when f.count>0 then round(ifnull(f.absentCount_JZXX,0)/f.count,4) else 0 end)/count(1),4)*100 as JZXXCQL -- 集中学习出勤率 from ZZ_ZZQKXX z inner join ( select f.ID,f.DW_ID as DZZDM,f.STUDY_START_TIME, count(1) as count, sum(case when f.STUDY_MODALITY_CODE='1' and (u.absent is null or u.absent=0) then 1 else 0 end) as absentCount_JZXX from ZZ_ZXZXX_FA f inner join ZZ_ZXZXX_CJLDBZ u on f.ID=u.CASE_ID where 1=1 and (f.deleted = 0 or f.deleted is null) and (u.deleted = 0 or u.deleted is null) and f.STUDY_MODALITY_CODE='1'
and Extract(year from f.STUDY_START_TIME)=#{year}
group by f.ID,f.DW_ID,f.STUDY_START_TIME ) f on z.DZZDM=f.DZZDM -- on z.DZZDM=substr(f.DZZDM, 0, length(z.DZZDM)) where 1=1 and z.DZZDM =#{dzzdm} group by z.DZZDM,f.STUDY_START_TIME order by z.DZZDM,f.STUDY_START_TIME

select z.DZZDM,sum(num) USERCOUNT from ZZ_ZZQKXX z inner join ( select z.DZZDM,count(1) as num from VM_RYJBXX u inner join ZZ_ZZQKXX z on u.SZDZBDM=z.DZZDM inner join rs_ryjbxxfb fb on u.RYBM = fb.RYBM where 1=1 and fb.partyDuesStartMonth <= #{yearMonth} group by z.DZZDM ) u on z.DZZDM=substr(u.DZZDM,1,length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select t1.xm1,t1.baseNumber1,t1.totalMoney1,t2.xm2,t2.baseNumber2,t2.totalMoney2
from (select ROWNUM as id,xm as xm1,baseNumber as baseNumber1,totalMoney as totalMoney1,null,null,null
      from (
             select ROWNUM,MOD(ROWNUM, 2) as type,t.xm,t.totalMoney,t.BASENUMBER
             from (
                    select us.XM,ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) as totalMoney,pd.BASENUMBER
                    from US_PARTYDUES pd
                           inner join US_PARTYDUES_DETAIL d on pd.PARTYDUESID = d.PARTYDUESID and d.payState=1
                           inner join VM_RYJBXX_ALL us on pd.USERCODE = us.rybm
                           inner join ZZ_ZZQKXX z on us.SZDZBDM=z.DZZDM
                           where 1=1 and pd.YEAR=#{year} and d.MONTH=#{month}
                           and  us.SZDZBDM like concat( '%',#{dzzdm},'%')
                    order by ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) desc
                  ) t
           )
      where 1 = 1 and type = 1
      order by ROWNUM
     ) t1
left join (
  select ROWNUM as id,null,null,null,XM as xm2,BASENUMBER as baseNumber2,TOTALMONEY as totalMoney2
  from (
         select ROWNUM,MOD(ROWNUM, 2) as type,t.xm,t.totalMoney,t.BASENUMBER
         from (
                select us.XM,ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) as totalMoney,pd.BASENUMBER
                from US_PARTYDUES pd
                       inner join US_PARTYDUES_DETAIL d on pd.PARTYDUESID = d.PARTYDUESID and d.payState=1
                       inner join VM_RYJBXX_ALL us on pd.USERCODE = us.rybm
                       inner join ZZ_ZZQKXX z on us.SZDZBDM=z.DZZDM
                       where 1=1 and pd.YEAR=#{year} and d.MONTH=#{month}
                       and  us.SZDZBDM like concat('%',#{dzzdm},'%')
                order by ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) desc
              ) t
       )
  where 1 = 1 and type = 0
  order by ROWNUM
) t2 on t1.id = t2.id

select z.DZZDM, #{year} as YEAR, sum(ifnull(pd.month1, 0)) as MONTH1, sum(ifnull(pd.month2, 0)) as MONTH2, sum(ifnull(pd.month3, 0)) as MONTH3, sum(ifnull(pd.month4, 0)) as MONTH4, sum(ifnull(pd.month5, 0)) as MONTH5, sum(ifnull(pd.month6, 0)) as MONTH6, sum(ifnull(pd.month7, 0)) as MONTH7, sum(ifnull(pd.month8, 0)) as MONTH8, sum(ifnull(pd.month9, 0)) as MONTH9, sum(ifnull(pd.month10, 0)) as MONTH10, sum(ifnull(pd.month11, 0)) as MONTH11, sum(ifnull(pd.month12, 0)) as MONTH12, sum(ifnull(pd.total, 0)) as TOTAL from ZZ_ZZQKXX z inner join ( select us.SZDZBDM as dzzdm, sum(case when d.MONTH = 1 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month1, sum(case when d.MONTH = 2 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month2, sum(case when d.MONTH = 3 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month3, sum(case when d.MONTH = 4 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month4, sum(case when d.MONTH = 5 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month5, sum(case when d.MONTH = 6 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month6, sum(case when d.MONTH = 7 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month7, sum(case when d.MONTH = 8 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month8, sum(case when d.MONTH = 9 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month9, sum(case when d.MONTH = 10 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month10, sum(case when d.MONTH = 11 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month11, sum(case when d.MONTH = 12 then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as month12, sum( ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0)) as total from US_PARTYDUES pd inner join US_PARTYDUES_DETAIL d on pd.PARTYDUESID = d.PARTYDUESID and d.payState=1 inner join VM_RYJBXX us on pd.USERCODE = us.rybm inner join ZZ_ZZQKXX z on us.SZDZBDM = z.DZZDM where 1=1 and us.SZDZBDM like concat('%',#{dzzdm},'%') and pd.YEAR=#{year} group by us.SZDZBDM ) pd on z.DZZDM = substr(pd.DZZDM, 1, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM, #{year} as year, sum(ifnull(pd.quarter1, 0)) as quarter1, sum(ifnull(pd.quarter2, 0)) as quarter2, sum(ifnull(pd.quarter3, 0)) as quarter3, sum(ifnull(pd.quarter4, 0)) as quarter4, sum(ifnull(pd.total, 0)) as total from ZZ_ZZQKXX z inner join ( select us.SZDZBDM as dzzdm, sum(case when d.MONTH in (1, 2, 3) then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as quarter1, sum(case when d.MONTH in (4, 5, 6) then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as quarter2, sum(case when d.MONTH in (7, 8, 9) then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as quarter3, sum(case when d.MONTH in (10, 11, 12) then ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0) else 0 end) as quarter4, sum(ifnull(d.MONEY, 0) + ifnull(d.SPECIALEXPENSES, 0)) as total from US_PARTYDUES pd inner join US_PARTYDUES_DETAIL d on pd.PARTYDUESID = d.PARTYDUESID and d.payState=1 inner join VM_RYJBXX us on pd.USERCODE = us.rybm inner join ZZ_ZZQKXX z on us.SZDZBDM = z.DZZDM where 1=1 and us.SZDZBDM like concat ( '%',#{dzzdm},'%') and pd.YEAR=#{year} group by us.SZDZBDM ) pd on z.DZZDM = substr(pd.DZZDM, 1, length(z.DZZDM)) where 1=1 and z.dzzdm in
#{dzzdm}
group by z.DZZDM

select z.DZZDM,z.DZZMC,zd.ID,zd.ACTIVITYTIME,zd.TITLE from DJ_ztdrxx zd
inner join ZZ_ZZQKXX z on zd.DZZDM = z.DZZDM
where 1=1

    and zd.dzzdm =#{dzzdm}


    and date_format(zd.ACTIVITYTIME,'%Y')= #{year}


    and date_format(zd.ACTIVITYTIME,'%m')= #{month}

order by z.DZZDM

select z.DZZDM, sum(ifnull(NUM_JZXX,0)) as NUM_JZXX, sum(ifnull(NUM_ZTYT,0)) as NUM_ZTYT from ZZ_ZZQKXX z left join ( select f.DW_ID as dzzdm, sum(case when f.STUDY_MODALITY_CODE='1' and date_format(f.STUDY_START_TIME, '%m') = #{month} then 1 else 0 end) as NUM_JZXX, -- 集中学习 sum(case when f.STUDY_MODALITY_CODE='2' and date_format(f.STUDY_START_TIME, 'Q') = #{quarter} then 1 else 0 end) as NUM_ZTYT -- 专题研讨 from ZZ_ZXZXX_FA f where 1=1 and (f.DELETED=0 or f.deleted is null) and Extract(year from f.STUDY_START_TIME)=#{year}
and f.DW_ID = #{dzzdm}
group by f.DW_ID ) f on z.DZZDM=f.DZZDM -- on z.DZZDM=substr(f.DZZDM, 0, length(z.DZZDM)) where 1=1
and z.dzzdm = #{dzzdm}
group by z.DZZDM
